    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = window.innerWidth, h = window.innerHeight;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
    canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);   // draw in css px
    cam.W = w; cam.H = h;
  }
  window.addEventListener('resize', resize);
  resize();

  function tri(c, pts, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y); ctx.lineTo(pts[1].x, pts[1].y); ctx.lineTo(pts[2].x, pts[2].y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
  }
  function quad(c, pts, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y); for (let i = 1; i < 4; i++) ctx.lineTo(pts[i].x, pts[i].y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 2; ctx.stroke(); }
  }
  const rgb = c => `rgb(${c[0]},${c[1]},${c[2]})`;

  function draw() {
    // backdrop
    ctx.fillStyle = rgb(BG); ctx.fillRect(0, 0, cam.W, cam.H);
    const m = buildRenderModel(die);
    // table (always behind the die in depth; drawn first)
    quad(ctx, m.table.pts, rgb(TABLE_TOP), rgb(TABLE_EDGE));
    // die faces, far -> near
    for (const f of m.faces) {
      tri(ctx, f.pts, rgb(f.color), rgb(f.color));
      // number
      const faceH = Math.max(
        Math.abs(f.pts[0].y - f.pts[1].y), Math.abs(f.pts[1].y - f.pts[2].y), Math.abs(f.pts[2].y - f.pts[0].y));
      const fs = clamp(0.5 * faceH, 8, 40);
      ctx.font = `800 ${fs.toFixed(1)}px system-ui, sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillStyle = f.labelDark ? 'rgb(24,28,44)' : 'rgb(240,242,250)';
      ctx.fillText(String(f.number), f.labelAt.x, f.labelAt.y);
    }
    // readout
    if (die.settled && lastSettled === false) lastSettled = true;
    if (die.settled && shown !== die.result) {
      shown = die.result;
      numEl.textContent = String(die.result);
      statusEl.textContent = 'settled';
    }
  }

  function rethrow() {
    const rng = D.prng((Math.floor(performance.now()) ^ 0x9E3779B9) >>> 0);
    die.pos = [ (rng()-0.5)*0.14, 0.14 + rng()*0.06, (rng()-0.5)*0.14 ];
    die.vel = [ (rng()-0.5)*3.0, -0.2 + rng()*0.5, (rng()-0.5)*3.0 ];
    die.angVel = [ (rng()-0.5)*55, (rng()-0.5)*55, (rng()-0.5)*55 ];
    die.quat = D.qNorm(D.qFromAxisAngle([rng()-0.5, rng()-0.5, rng()-0.5], rng()*Math.PI*2));
    for (let k = 0; k < 2; k++) die.quat = D.qNorm(D.qMul(D.qFromAxisAngle([rng()-0.5,rng()-0.5,rng()-0.5], rng()*Math.PI*2), die.quat));
    die.t = 0; die.steps = 0; die.settled = false; die.stillTimer = 0; die.result = 0;
    shown = null; lastSettled = false;
    numEl.textContent = '…'; statusEl.textContent = 'rolling';
  }

  const params = new URLSearchParams(window.location.search);
  const demo = params.get('demo') === '1';
  if (demo) document.getElementById('diego').textContent = 'demo (auto-throw)';
  if (demo) rethrow();
  let demoTimer = null;
  if (demo) demoTimer = setInterval(() => { if (die.settled) rethrow(); }, 2600);

  let last = performance.now();
  function frame(now) {
    let dt = (now - last) / 1000; last = now;
    if (dt > 0.1) dt = 0.1;               // clamp big gaps (tab was backgrounded)
    if (grab.active) {
      constrainedStep(dt);                // hand holds the die: no free physics
    } else if (!die.settled) {
      D.advance(die, dt);                 // free physics: gravity, table, walls
    }
    die.contacts.length = 0;  // clear contact events after each frame (sound seam)
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // ============================ GRAB & THROW ============================
  // Rigid hold: while grabbed, the die is kinematically driven so the grabbed
  // face point tracks the cursor (soft gain). On release, the die flies with
  // the velocity it had from being swung — no impulse, no seed.
  const grab = {
    active: false,
    face: -1,
    bary: null,       // barycentric coords of the grab point on the face
    world: null,      // world position of the grab point at pick time
    cursorX: 0,       // current pointer x (css px)
    cursorY: 0        // current pointer y (css px)
  };
  const GRAB_GAIN = 15;       // soft gain: point velocity = K * error (1/s)
  const GRAB_VMAX = 6.0;      // clamp |die.vel| while held (m/s)
  const GRAB_WMAX = 60.0;     // clamp |die.angVel| while held (rad/s)

  function pointerPos(e) {
    const rect = canvas.getBoundingClientRect();
    const cx = e.touches ? e.touches[0].clientX : e.clientX;
    const cy = e.touches ? e.touches[0].clientY : e.clientY;
    return { x: cx - rect.left, y: cy - rect.top };
  }

  function startGrab(px, py) {
    if (demo) return; // don't fight the auto-throw
    const hit = pickFace(px, py, die);
    if (!hit) return;
    grab.active = true;
    grab.face = hit.face;
    grab.bary = hit.bary;
    grab.world = hit.world;
    grab.cursorX = px;
    grab.cursorY = py;
    // wake the die so it can be thrown even if settled
    if (die.settled) {
      die.settled = false;
      die.stillTimer = 0;
      die.result = 0;
      shown = null;
      lastSettled = false;
      numEl.textContent = '…';
      statusEl.textContent = 'rolling';
    }
    canvas.style.cursor = 'grabbing';
  }

  function moveGrab(px, py) {
    if (!grab.active) return;
    grab.cursorX = px;
    grab.cursorY = py;
  }

  // Constrained step: while grabbed, drive the die so the grabbed face point
  // tracks the cursor target with a soft gain. No free physics (no gravity,
  // no table contact) — the hand holds the die.
  function constrainedStep(dt) {
    // Cursor target in world space: intersect the unprojected cursor ray with
    // the plane through grab.world facing the camera (normal = camera forward).
    const ray = unproject(grab.cursorX, grab.cursorY);
    const { f } = basis();
    const denom = dot(ray.dir, f);
    let T;
    if (Math.abs(denom) < 1e-6) {
      T = grab.world.slice(); // ray parallel to plane: no movement
    } else {
      const t = dot(sub(grab.world, ray.origin), f) / denom;
      T = [ ray.origin[0] + ray.dir[0]*t, ray.origin[1] + ray.dir[1]*t, ray.origin[2] + ray.dir[2]*t ];
    }

    // Current world position of the grabbed point.
    // P_local = barycentric combination of the face's 3 local vertices.
