// Dev harness (dev-only, not shipped): headless check of the s2 renderer.
// Extracts the physics-core AND renderer <script> blocks from index.html and
// evals them in node (the renderer's browser half no-ops when window is
// undefined, so globalThis.DICE is defined with no DOM). Verifies the pure
// math: projection, painter's-algorithm model, and picking. Usage: node render_test.mjs
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, 'index.html'), 'utf8');

function block(id) {
  const start = html.indexOf(`<script id="${id}">`);
  const end = html.indexOf(`</script>`, start);
  if (start < 0 || end < 0) throw new Error('missing <script id="' + id + '">');
  return html.slice(start + `<script id="${id}">`.length, end);
}

(0, eval)(block('physics-core'));
(0, eval)(block('renderer'));

const D = globalThis.D20;
const R = globalThis.DICE;
if (!R) { console.error('FAIL: global.DICE not defined after eval'); process.exit(1); }

// --- deterministic settled die (same initial state as the self-test's det check)
const die = D.createD20();
die.pos = [0.02, 0.12, -0.01];
die.vel = [0.6, -0.2, 0.35];
die.angVel = [18, -9, 12];
die.quat = D.qFromAxisAngle([1, 2, 3], 0.7);
D.advance(die, 40);
const num = D.faceUp(die);
const fi = R.faceIndexOfNumber(die);

let ok = true;
const fail = m => { ok = false; console.error('FAIL: ' + m); };
const pass = m => console.log('ok:   ' + m);

// (a) the 4 table corners project within canvas bounds
const m = R.buildRenderModel(die);
const inBounds = m.table.pts.every(p => p.x >= 0 && p.x <= R.cam.W && p.y >= 0 && p.y <= R.cam.H);
if (inBounds) pass('table corners within canvas (' + m.table.pts.map(p => Math.round(p.x) + ',' + Math.round(p.y)).join(' ') + ')');
else fail('table corners out of canvas bounds: ' + m.table.pts.map(p => p.x + ',' + p.y).join(' '));

// (b) visible face count is sane for a convex d20 (a few, never more than ~10)
if (m.faces.length >= 5 && m.faces.length <= 12) pass(m.faces.length + ' visible faces (convex d20 reads ~9)');
else fail('visible face count out of range: ' + m.faces.length);

// (c) painter's sort: depths are non-increasing front->... far->near
let sorted = true;
for (let i = 1; i < m.faces.length; i++) if (m.faces[i].depth > m.faces[i - 1].depth + 1e-9) sorted = false;
if (sorted) pass('faces sorted far->near');
else fail('faces not sorted far->near');

// (d) the settled face-up face is rendered AND is the brightest (landing boost)
const isRendered = m.faces.some(f => f.f === fi);
if (isRendered) pass('face-up face ' + fi + ' (number ' + num + ') is rendered');
else fail('face-up face ' + fi + ' not in render model');

const byF = f => m.faces.find(x => x.f === f);
if (m.faces.length >= 2) {
  const top = byF(fi);
  const others = m.faces.filter(f => f.f !== fi);
  const lum = c => 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];
  const landLum = lum(top.color);
  // the landing face should not be the darkest of the visible faces
  const anyDarker = others.some(f => lum(f.color) < landLum);
  if (anyDarker) pass('landing face lum ' + Math.round(landLum) + ' has darker neighbours (boost visible)');
  else fail('landing face not brighter than others (lum ' + Math.round(landLum) + ')');
}

// (e) pickFace at the face-up face's projected screen center returns that face
const cc = R.project(D.faceCenterWorld(die, fi));
const hit = R.pickFace(Math.round(cc.x), Math.round(cc.y), die);
if (hit && hit.face === fi) pass('pickFace at face-up center -> face ' + hit.face + ' (number ' + hit.number + ')');
else fail('pickFace at face-up center -> ' + (hit ? 'face ' + hit.face + ' (number ' + hit.number + ')' : 'null'));

// (f) pickFace at canvas center doesn't crash (null or a face)
const centerHit = R.pickFace(Math.round(R.cam.W / 2), Math.round(R.cam.H / 2), die);
pass('pickFace at canvas center -> ' + (centerHit ? 'face ' + centerHit.face : 'null') + ' (no crash)');

// (g) buildRenderModel does not mutate die state
const snapBefore = JSON.stringify({ p: die.pos, q: die.quat, v: die.vel, w: die.angVel, t: die.t, s: die.steps });
R.buildRenderModel(die);
const snapAfter = JSON.stringify({ p: die.pos, q: die.quat, v: die.vel, w: die.angVel, t: die.t, s: die.steps });
if (snapBefore === snapAfter) pass('buildRenderModel does not mutate die state');
else fail('buildRenderModel mutated die state');

// (h) rayTablePlane: a ray from the camera down hits the table at y=0 within bounds
const ray = R.unproject(R.cam.W / 2, R.cam.H / 2);
const tp = R.rayTablePlane(ray);
if (tp && tp.point[1] === 0 && Math.abs(tp.point[0]) <= R.TABLE + 1e-6 && Math.abs(tp.point[2]) <= R.TABLE + 1e-6)
  pass('screen center ray -> table point [' + tp.point.map(v => v.toFixed(3)).join(',') + ']');
else fail('screen center ray did not hit table in bounds: ' + JSON.stringify(tp));

console.log('RESULT ' + (ok ? 'PASS' : 'FAIL') + '  (settled die shows face ' + num + ', render face ' + fi + ')');
process.exit(ok ? 0 : 1);

